SELECT *, LAG(sqft, 1) OVER (PARTITION BY city ORDER BY sqft, id) AS prev_sqft, MIN(sqft) OVER (PARTITION BY region) AS region_min_sqft, AVG(sqft) OVER (PARTITION BY city, region ORDER BY opened_date, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS sqft_avg_2_prior, FIRST_VALUE(sqft, TRUE) OVER (PARTITION BY city ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_sqft FROM stores WHERE sqft < 7525;
